S.append(S2(c,B+' · 2','Đảo từ trong câu, đếm từ, chuẩn hoá',card('Các thao tác tổ hợp',P('Đảo thứ tự từ: <code>" ".join(s.split()[::-1])</code>.','Đếm số từ: <code>len(s.split())</code>.','Chuẩn hoá khoảng trắng: <code>" ".join(s.split())</code>.','Viết hoa chữ cái đầu mỗi từ: <code>s.title()</code>.')),CODE('s = "  to be   or not to be "\nw = s.split()\nprint(len(w), w.count("be"), w[::-1][0])\nprint(" ".join(w[::-1]))\nprint(" ".join(w).title())\nprint("Dang nang 2026".split()[0][::-1])',20)+R('s = "  to be   or not to be "\nw = s.split()\nprint(len(w), w.count("be"), w[::-1][0])\nprint(" ".join(w[::-1]))\nprint(" ".join(w).title())\nprint("Dang nang 2026".split()[0][::-1])','',22,'Kết quả')))
