S.append(S2(c,B+' · 3','Duyệt xâu: hai cách',card('Theo kí tự hoặc theo chỉ số',P('<code>for c in s:</code> lấy từng kí tự — gọn, dùng khi <b>không cần vị trí</b>.','<code>for i in range(len(s)):</code> — dùng khi cần <b>vị trí</b> hoặc so sánh kí tự <b>kề nhau</b>.','<code>for i, c in enumerate(s):</code> — có cả hai.')),CODE('s = "a1b22c333"\nd = 0\nfor ch in s:\n    if ch.isdigit():\n        d += int(ch)\nprint(d)\nliên = 0\nfor i in range(1, len(s)):\n    if s[i] == s[i - 1]:\n        liên += 1\nprint(liên)'.replace('liên','lien'),20)+R('s = "a1b22c333"\nd = 0\nfor ch in s:\n    if ch.isdigit():\n        d += int(ch)\nprint(d)\nlien = 0\nfor i in range(1, len(s)):\n    if s[i] == s[i - 1]:\n        lien += 1\nprint(lien)','',22,'Kết quả')+KEY('Tổng chữ số: 1 + 2 + 2 + 3 + 3 + 3 = <b>14</b>. Cặp kề bằng nhau: “22”, “33”, “33” → <b>3</b>.')))
S.append(S2(c,B+' · 3','Xâu đối xứng (palindrome)',card('Ba cách kiểm tra',P('<b>Cách 1</b>: <code>s == s[::-1]</code>.','<b>Cách 2</b>: hai chỉ số i, j chạy vào giữa.','Thường <b>chuẩn hoá</b> trước: bỏ khoảng trắng, đổi chữ thường.')),CODE('def dx(s):\n    t = "".join(c.lower() for c in s if c.isalnum())\n    return t == t[::-1]\n\nprint(dx("Level"), "Level" == "Level"[::-1])\nprint(dx("A man, a plan, a canal: Panama"))\nprint(dx("Da Nang"))',20)+R('def dx(s):\n    t = "".join(c.lower() for c in s if c.isalnum())\n    return t == t[::-1]\n\nprint(dx("Level"), "Level" == "Level"[::-1])\nprint(dx("A man, a plan, a canal: Panama"))\nprint(dx("Da Nang"))','',22,'Kết quả')+KEY('“Level” đối xứng nếu <b>bỏ qua hoa thường</b>; so sánh trực tiếp thì không (L ≠ l).')))
S.append(S2(c,B+' · 3','Mật mã Caesar (dịch vòng k vị trí)',card('Ý tưởng',P('Mỗi chữ thường được dịch <b>k vị trí</b> trong bảng chữ cái, <b>quay vòng</b> sau z.','Công thức: <code>chr((ord(c) − ord("a") + k) % 26 + ord("a"))</code>.','Kí tự khác chữ thường giữ nguyên.','<b>Giải mã</b> = mã hoá với <b>26 − k</b> (hoặc −k).')),CODE('def mh(s, k):\n    kq = ""\n    for c in s:\n        if "a" <= c <= "z":\n            kq += chr((ord(c) - 97 + k) % 26 + 97)\n        else:\n            kq += c\n    return kq\nprint(mh("xyz abc", 3))\nprint(mh(mh("tin hoc", 5), 21))',19)+R('def mh(s, k):\n    kq = ""\n    for c in s:\n        if "a" <= c <= "z":\n            kq += chr((ord(c) - 97 + k) % 26 + 97)\n        else:\n            kq += c\n    return kq\nprint(mh("xyz abc", 3))\nprint(mh(mh("tin hoc", 5), 21))','',22,'Kết quả')+KEY('Mã hoá 5 rồi 21: 5 + 21 = <b>26</b> ≡ 0 nên <b>trở về xâu gốc</b>.')))
S.append(S2(c,B+' · 3','Nén xâu: đếm các kí tự liên tiếp',card('Mã hoá độ dài chạy (RLE)',P('Chuyển “aaabccdd” thành “a3b1c2d2”: mỗi kí tự kèm <b>số lần lặp liên tiếp</b>.','Duyệt bằng chỉ số; <b>nhớ kí tự trước</b> và đếm.','Nhớ ghi nốt nhóm cuối sau vòng lặp!')),CODE('s = "aaabccdd"\nkq = ""\ni = 0\nwhile i < len(s):\n    j = i\n    while j < len(s) and s[j] == s[i]:\n        j += 1\n    kq += s[i] + str(j - i)\n    i = j\nprint(kq)',21)+R('s = "aaabccdd"\nkq = ""\ni = 0\nwhile i < len(s):\n    j = i\n    while j < len(s) and s[j] == s[i]:\n        j += 1\n    kq += s[i] + str(j - i)\n    i = j\nprint(kq)','',24,'Kết quả')+KEY('Hai vòng <b>while lồng</b> nhưng mỗi kí tự chỉ được duyệt <b>một lần</b> (i nhảy tới j) → tuyến tính.')))
S.append(S2(c,B+' · 3','Đếm tần suất kí tự bằng dict',card('Kĩ thuật dùng nhiều nhất',P('Dùng từ điển: <code>d[c] = d.get(c, 0) + 1</code>.','<code>d.get(k, 0)</code> trả 0 nếu chưa có khoá, tránh lỗi KeyError.','Kí tự xuất hiện nhiều nhất: <code>max(d, key=d.get)</code>.')),CODE('s = "tin hoc ung dung"\nd = {}\nfor c in s:\n    if c != " ":\n        d[c] = d.get(c, 0) + 1\nprint(d)\nprint(max(d, key=d.get), max(d.values()))',21)+R('s = "tin hoc ung dung"\nd = {}\nfor c in s:\n    if c != " ":\n        d[c] = d.get(c, 0) + 1\nprint(d)\nprint(max(d, key=d.get), max(d.values()))','',20,'Kết quả')+KEY('Có nhiều kí tự cùng tần suất thì <code>max</code> chọn <b>kí tự xuất hiện sớm nhất</b> trong từ điển.')))
